begin;
select no_plan();
\ir ../support/academic-fixture.psql
select has_function('public','get_admin_catalog',array['jsonb'],'administrative catalogue exists');
select has_function('public','save_demo_scope',array['jsonb','uuid','integer','jsonb','uuid'],'scope command exists');
select has_function('public','set_demo_business_link',array['jsonb','uuid','integer','jsonb','uuid'],'business link command exists');
insert into auth.users(id,email,aud,role) values(pg_temp.fixture('admin'),'admin-t12@example.invalid','authenticated','authenticated'),(pg_temp.fixture('outsider'),'outside-t12@example.invalid','authenticated','authenticated');
insert into public.contas_demo(ator_id,rotulo) select pg_temp.fixture(who),'DEMO-'||who from unnest(array['admin','actor','reviewer'])who;
insert into public.vinculos(actor_id,papel,escopo_id,indicador_id,vigencia_inicio) values(pg_temp.fixture('admin'),'administrador',pg_temp.fixture('district'),'c0de0000-0000-4000-8000-000000000002',current_date-1),(pg_temp.fixture('actor'),'area_tecnica',pg_temp.fixture('district'),'c0de0000-0000-4000-8000-000000000002',current_date-1);
create function pg_temp.admin_ctx() returns jsonb language sql security definer as $$select jsonb_build_object('vinculoId',id,'competenciaId',pg_temp.fixture('competence'),'indicadorId',indicador_id) from public.vinculos where actor_id=pg_temp.fixture('admin');$$;
create function pg_temp.technical_ctx() returns jsonb language sql security definer as $$select jsonb_build_object('vinculoId',id,'competenciaId',pg_temp.fixture('competence'),'indicadorId',indicador_id) from public.vinculos where actor_id=pg_temp.fixture('actor') and indicador_id is not null;$$;
create function pg_temp.link_input(role_name text default 'cam',scope uuid default null,active boolean default true) returns jsonb language sql as $$select jsonb_build_object('role',role_name,'escopoId',coalesce(scope,pg_temp.fixture('unit')),'indicadorId','c0de0000-0000-4000-8000-000000000002','ativo',active,'vigenciaInicio',(current_date-1)::text,'vigenciaFim',null);$$;
select pg_temp.login_as('admin');set local role authenticated;
select ok(not(public.get_admin_catalog(pg_temp.admin_ctx())::text like '%email%'),'catalogue excludes Auth email');
select ok(not(public.get_admin_catalog(pg_temp.admin_ctx())::text like '%valor%'),'catalogue excludes evaluation values');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('admin'),0,pg_temp.link_input(),gen_random_uuid())$$,'42501','access_denied','cannot grant own CAM');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('actor'),0,pg_temp.link_input('administrador'),gen_random_uuid())$$,'42501','access_denied','cannot grant any administrator');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('outsider'),0,pg_temp.link_input(),gen_random_uuid())$$,'42501','access_denied','non-provisioned target rejected');
select throws_ok($$select public.save_demo_scope(pg_temp.admin_ctx(),null,0,'{"codigo":"TEST-UNIT","tipo":"distrito","distritoId":null,"ativo":true}',gen_random_uuid())$$,'22023','invalid_input','duplicate code rejected');
select throws_ok($$select public.save_demo_scope(pg_temp.admin_ctx(),null,0,jsonb_build_object('codigo','NEW-UNIT','tipo','unidade','distritoId',pg_temp.fixture('unit'),'ativo',true),gen_random_uuid())$$,'22023','invalid_input','unit cannot be parent district');
create temporary table admin_saved(label text primary key,receipt jsonb);
insert into admin_saved values('district',public.save_demo_scope(pg_temp.admin_ctx(),null,0,'{"codigo":"DEMO-NEW-DISTRICT","tipo":"distrito","distritoId":null,"ativo":true}',pg_temp.fixture('new-district-op')));
select is((select receipt->>'version' from admin_saved where label='district'),'1','new scope starts at version one');
select is(public.save_demo_scope(pg_temp.admin_ctx(),null,0,'{"codigo":"  DEMO-NEW-DISTRICT  ","tipo":"distrito","distritoId":null,"ativo":true}',pg_temp.fixture('new-district-op')),(select receipt from admin_saved where label='district'),'canonical retry before stale creation version');
select throws_ok($$select public.save_demo_scope(pg_temp.admin_ctx(),null,0,'{"codigo":"DIFFERENT","tipo":"distrito","distritoId":null,"ativo":true}',pg_temp.fixture('new-district-op'))$$,'22023','operation_payload_mismatch','same UUID different scope payload rejected');
select throws_ok($$select public.save_demo_scope(pg_temp.admin_ctx(),pg_temp.fixture('district'),0,'{"codigo":"TEST-DISTRICT","tipo":"distrito","distritoId":null,"ativo":true}',gen_random_uuid())$$,'40001','version_conflict','stale scope version rejected');
select throws_ok($$select public.save_demo_scope(pg_temp.admin_ctx(),pg_temp.fixture('unit'),1,'{"codigo":"TEST-UNIT","tipo":"distrito","distritoId":null,"ativo":true}',gen_random_uuid())$$,'22023','invalid_input','referenced scope cannot change historical type');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('reviewer'),0,pg_temp.link_input('lideranca',pg_temp.fixture('unit')),gen_random_uuid())$$,'22023','invalid_input','leadership requires district');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('reviewer'),0,pg_temp.link_input()||'{"password":"do-not-accept"}'::jsonb,gen_random_uuid())$$,'22023','invalid_input','Auth attributes rejected');
insert into admin_saved values('link',public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('reviewer'),0,pg_temp.link_input(),pg_temp.fixture('grant-link-op')));
select is((select receipt->>'version' from admin_saved where label='link'),'1','new business link version one');
select is(public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('reviewer'),0,pg_temp.link_input(),pg_temp.fixture('grant-link-op')),(select receipt from admin_saved where label='link'),'link retry once');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('reviewer'),0,pg_temp.link_input('cam',null,false),gen_random_uuid())$$,'40001','version_conflict','stale link update rejected');
select throws_ok($$select public.transition_cycle(pg_temp.admin_ctx(),1,'close','','DEMO-DECISAO-ADMIN',gen_random_uuid())$$,'42501','access_denied','administrator cannot act as CAM');
select throws_ok($$select public.get_operational_positions(pg_temp.admin_ctx(),'{"page":1,"pageSize":25}')$$,'42501','access_denied','administrator has no operational access');
select ok(not exists(select 1 from jsonb_array_elements(public.get_scoped_audit(pg_temp.admin_ctx(),'{"page":1,"pageSize":100}')->'items')a where a->'reason'<>'null'::jsonb or a? 'actorId' or a?'details'),'administrative history is sanitized');
select ok(exists(select 1 from jsonb_array_elements(public.get_scoped_audit(pg_temp.admin_ctx(),'{"page":1,"pageSize":100}')->'items')a where a->>'action'='escopo_demo_salvo' and a->>'resourceId'=(select receipt->>'resourceId' from admin_saved where label='district') and a->>'version'='1'),'scope event correct resource and version');
select ok(exists(select 1 from jsonb_array_elements(public.get_scoped_audit(pg_temp.admin_ctx(),'{"page":1,"pageSize":100}')->'items')a where a->>'action'='vinculo_demo_alterado' and a->>'resourceId'=(select receipt->>'resourceId' from admin_saved where label='link') and a->>'version'='1'),'link event correct resource and version');
reset role;
select is((select count(*)::integer from public.eventos_auditoria where correlacao_id=pg_temp.fixture('new-district-op')),1,'scope replay emits one event');
select is((select count(*)::integer from public.eventos_auditoria where correlacao_id=pg_temp.fixture('grant-link-op')),1,'link replay emits one event');
select ok(not exists(select 1 from public.eventos_auditoria where acao in ('escopo_demo_salvo','vinculo_demo_alterado') and detalhes-'version'<>'{}'::jsonb),'admin event includes only cadastral version');
-- A real closed snapshot is created by the existing cycle commands, not by
-- disabling its guards or inserting fabricated acceptance.
insert into public.competencias(id,codigo,referencia,estado,modelo) values(pg_temp.fixture('admin-past'),'DEMO-ADMIN-PAST','2026-08-01','aberta',2);
insert into public.territorios_competencia(competencia_id,unidade_id,distrito_id) values(pg_temp.fixture('admin-past'),pg_temp.fixture('unit'),pg_temp.fixture('district'));
insert into public.posicoes_esperadas(id,competencia_id,indicador_id,alvo_id,regra_id,aplicavel,informante_id,revisor_id) values(pg_temp.fixture('past-na'),pg_temp.fixture('admin-past'),'c0de0000-0000-4000-8000-000000000002',pg_temp.fixture('unit'),'c0de0000-0000-4000-8000-000000000004',false,pg_temp.fixture('actor'),pg_temp.fixture('reviewer'));
create function pg_temp.past_ctx() returns jsonb language sql security definer as $$select jsonb_build_object('vinculoId',id,'competenciaId',pg_temp.fixture('admin-past'),'indicadorId',indicador_id) from public.vinculos where actor_id=pg_temp.fixture('reviewer') and papel='cam';$$;
select pg_temp.login_as('reviewer');set local role authenticated;
select public.transition_cycle(pg_temp.past_ctx(),1,'consolidate','','',gen_random_uuid());
select public.transition_cycle(pg_temp.past_ctx(),2,'close','','DEMO-DECISAO-ADMIN-PAST',gen_random_uuid());
insert into admin_saved select 'snapshot',public.get_snapshot_export(pg_temp.past_ctx(),(public.get_cycle_checklist(pg_temp.past_ctx())->>'snapshotId')::uuid,gen_random_uuid());
select pg_temp.login_as('admin');
select public.save_demo_scope(pg_temp.admin_ctx(),pg_temp.fixture('unit'),1,jsonb_build_object('codigo','CHANGED-FUTURE-UNIT','tipo','unidade','distritoId',(select receipt->>'resourceId' from admin_saved where label='district'),'ativo',false),pg_temp.fixture('move-scope-op'));
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('actor'),0,pg_temp.link_input('cam'),gen_random_uuid())$$,'22023','invalid_input','inactive scope forbids new business link');
select pg_temp.login_as('reviewer');
select is(public.get_snapshot_export(pg_temp.past_ctx(),(select (receipt->>'snapshotId')::uuid from admin_saved where label='snapshot'),gen_random_uuid()),(select receipt from admin_saved where label='snapshot'),'admin territorial change and deactivation do not rewrite past snapshot');
reset role;
select is((select distrito_id from public.territorios_competencia where competencia_id=pg_temp.fixture('admin-past') and unidade_id=pg_temp.fixture('unit')),pg_temp.fixture('district'),'frozen territory preserved');
select is((select alvo_codigo from public.itens_fechamento where posicao_id=pg_temp.fixture('past-na')),'TEST-UNIT','frozen target code preserved');
-- Inactive catalogue does not revoke authorization for an already fixed target.
select pg_temp.login_as('admin');set local role authenticated;
select public.save_demo_scope(pg_temp.admin_ctx(),pg_temp.fixture('district'),1,'{"codigo":"TEST-DISTRICT","tipo":"distrito","distritoId":null,"ativo":false}',pg_temp.fixture('deactivate-district-op'));
select pg_temp.login_as('actor');
insert into admin_saved values('draft',public.save_position_draft(pg_temp.technical_ctx(),pg_temp.fixture('other_position'),1,'{"estadoDado":"valor","valor":"10","fonte":"DEMO","periodoFonte":"2026-10-01","motivo":""}',pg_temp.fixture('draft-before-revoke')));
select ok(exists(select 1 from jsonb_array_elements(public.get_authorized_contexts()->'contexts')a where a->>'escopoId'=pg_temp.fixture('district')::text),'inactive scope preserves existing fixed context');
select throws_ok($$select public.get_admin_catalog(pg_temp.technical_ctx())$$,'42501','access_denied','technical account cannot read admin catalogue');
select pg_temp.login_as('admin');
select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('actor'),1,pg_temp.link_input('area_tecnica',pg_temp.fixture('district'),false),pg_temp.fixture('revoke-tech-op'));
select pg_temp.login_as('actor');
select throws_ok($$select public.save_position_draft(pg_temp.technical_ctx(),pg_temp.fixture('other_position'),1,'{"estadoDado":"valor","valor":"10","fonte":"DEMO","periodoFonte":"2026-10-01","motivo":""}',pg_temp.fixture('draft-before-revoke'))$$,'42501','access_denied','revocation denies completed retry before cache');
select throws_ok($$select public.save_position_draft(pg_temp.technical_ctx(),pg_temp.fixture('other_position'),2,'{"estadoDado":"valor","valor":"12","fonte":"DEMO","periodoFonte":"2026-10-01","motivo":""}',gen_random_uuid())$$,'42501','access_denied','revocation denies next command without logout');
select is(public.get_authorized_contexts()->'contexts','[]'::jsonb,'revoked account has no academic context (legacy link still distinct)');
reset role;
update public.contas_demo set ativo=false where ator_id=pg_temp.fixture('reviewer');
select pg_temp.login_as('admin');set local role authenticated;
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('reviewer'),1,pg_temp.link_input(),gen_random_uuid())$$,'42501','access_denied','inactive account cannot receive a business link');
select pg_temp.login_as('reviewer');
select is(public.get_authorized_contexts()->'contexts','[]'::jsonb,'inactive account has no contexts');
select throws_ok($$select public.get_admin_catalog(pg_temp.past_ctx())$$,'42501','access_denied','CAM cannot call administrative RPC');
reset role;
select ok(not has_function_privilege('anon','public.get_admin_catalog(jsonb)','execute'),'anonymous catalogue denied');
select ok(not has_function_privilege('authenticated','private.administer_academic_metadata(jsonb,text,jsonb,uuid)','execute'),'private helper denied');
select ok(not has_function_privilege('service_role','private.administer_academic_metadata(jsonb,text,jsonb,uuid)','execute'),'service role private helper denied');
select pg_temp.login_as('admin');set local role authenticated;
select throws_ok('select * from public.contas_demo','42501',null,'direct account catalogue denied');
select throws_ok($$update public.escopos set ativo=true where id=pg_temp.fixture('unit')$$,'42501',null,'direct scope write denied');
reset role;
-- T12 review regression: an inactive catalogue cannot be bypassed by extending
-- dates of a link that was never toggled to inactive. Check persisted state
-- immediately after each attempted RPC, not merely after transaction rollback.
insert into auth.users(id,email,aud,role) values(pg_temp.fixture('window-actor'),'window-t12@example.invalid','authenticated','authenticated');
insert into public.contas_demo(ator_id,rotulo) values(pg_temp.fixture('window-actor'),'DEMO-window-actor');
insert into public.escopos(id,codigo,tipo,ativo) select pg_temp.fixture('window-scope-'||n),'DEMO-WINDOW-'||n,'distrito',false from generate_series(1,5)n;
insert into public.posicoes_esperadas(id,competencia_id,indicador_id,alvo_id,regra_id,aplicavel,informante_id,revisor_id)
select pg_temp.fixture('window-position-'||n),pg_temp.fixture('competence'),'c0de0000-0000-4000-8000-000000000002',pg_temp.fixture('window-scope-'||n),'c0de0000-0000-4000-8000-000000000004',false,pg_temp.fixture('actor'),pg_temp.fixture('reviewer') from generate_series(1,5)n;
insert into public.vinculos(id,actor_id,papel,escopo_id,indicador_id,ativo,vigencia_inicio,vigencia_fim)
select pg_temp.fixture('window-link-'||n),pg_temp.fixture('window-actor'),'cam',pg_temp.fixture('window-scope-'||n),case when n=5 then null else 'c0de0000-0000-4000-8000-000000000002'::uuid end,true,
case when n=5 then null when n=2 then current_date+10 else current_date-10 end,
case when n=1 then current_date-1 when n=2 then current_date+20 when n=3 then current_date+10 else null end from generate_series(1,5)n;
create function pg_temp.window_input(n integer,start_on date,end_on date,active boolean default true) returns jsonb language sql as $$select jsonb_build_object('role','cam','escopoId',pg_temp.fixture('window-scope-'||n),'indicadorId','c0de0000-0000-4000-8000-000000000002','ativo',active,'vigenciaInicio',start_on::text,'vigenciaFim',end_on::text);$$;
create function pg_temp.window_state(n integer,op text) returns jsonb language sql security definer as $$select jsonb_build_object('version',v.lock_version,'start',v.vigencia_inicio,'end',v.vigencia_fim,'active',v.ativo,'indicator',v.indicador_id,'events',(select count(*) from public.eventos_auditoria where recurso_id=v.id),'operations',(select count(*) from public.operacoes_dominio where ator_id=pg_temp.fixture('admin') and operation_id=pg_temp.fixture(op))) from public.vinculos v where id=pg_temp.fixture('window-link-'||n);$$;
create temporary table window_before(n integer primary key,state jsonb);
insert into window_before select n,pg_temp.window_state(n,'window-reject-'||n) from generate_series(1,5)n;
grant select on window_before to authenticated;
select pg_temp.login_as('window-actor');set local role authenticated;
select ok(not exists(select 1 from jsonb_array_elements(public.get_authorized_contexts()->'contexts')c where c->>'vinculoId' in (pg_temp.fixture('window-link-1')::text,pg_temp.fixture('window-link-2')::text,pg_temp.fixture('window-link-5')::text)),'expired/future/null-start links have no academic context before attempts');
select ok(exists(select 1 from jsonb_array_elements(public.get_authorized_contexts()->'contexts')c where c->>'vinculoId'=pg_temp.fixture('window-link-3')::text),'current window keeps fixed association in inactive scope');
select pg_temp.login_as('admin');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(1,current_date-10,null),pg_temp.fixture('window-reject-1'))$$,'22023','invalid_input','expired active link cannot restore access by unbounding end');
select is(pg_temp.window_state(1,'window-reject-1'),(select state from window_before where n=1),'expired rejection preserves dates/version/event and operation counts');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(2,current_date,current_date+20),pg_temp.fixture('window-reject-2'))$$,'22023','invalid_input','future active link cannot restore access by earlier start');
select is(pg_temp.window_state(2,'window-reject-2'),(select state from window_before where n=2),'future rejection preserves dates/version/event and operation counts');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(3,current_date-10,null),pg_temp.fixture('window-reject-3'))$$,'22023','invalid_input','finite current active link cannot expand end to unbounded');
select is(pg_temp.window_state(3,'window-reject-3'),(select state from window_before where n=3),'finite rejection preserves dates/version/event and operation counts');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(3,current_date-10,current_date+11),pg_temp.fixture('window-reject-finite-end'))$$,'22023','invalid_input','finite end cannot expand even when it remains bounded');
select is(pg_temp.window_state(3,'window-reject-finite-end'),(select state from window_before where n=3),'bounded end expansion rejection preserves row/events/operation count');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(4,current_date-20,null),pg_temp.fixture('window-reject-4'))$$,'22023','invalid_input','unbounded active link cannot expand start backwards');
select is(pg_temp.window_state(4,'window-reject-4'),(select state from window_before where n=4),'earlier-start rejection preserves dates/version/event and operation counts');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(5,current_date-10,null),pg_temp.fixture('window-reject-5'))$$,'22023','invalid_input','null-start legacy collision never gains academic authority');
select is(pg_temp.window_state(5,'window-reject-5'),(select state from window_before where n=5),'null legacy start and indicator remain unchanged with no event/operation');
select pg_temp.login_as('window-actor');
select ok(not exists(select 1 from jsonb_array_elements(public.get_authorized_contexts()->'contexts')c where c->>'vinculoId' in (pg_temp.fixture('window-link-1')::text,pg_temp.fixture('window-link-2')::text,pg_temp.fixture('window-link-5')::text)),'denied attempts do not give expired/future/legacy links context');
select pg_temp.login_as('admin');
select lives_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(1,current_date-10,current_date-1),pg_temp.fixture('window-unchanged'))$$,'unchanged expired window remains maintainable');
select lives_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(2,current_date+11,current_date+19),pg_temp.fixture('window-narrow-future'))$$,'narrowing future window is permitted without restoring current access');
select lives_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(3,current_date-5,current_date+5),pg_temp.fixture('window-narrow-current'))$$,'narrowing current finite window is permitted');
select lives_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(4,current_date-5,current_date+5),pg_temp.fixture('window-narrow-unbounded'))$$,'unbounded end may be restricted to finite date');
select is(pg_temp.window_state(3,'window-narrow-current'),jsonb_build_object('version',2,'start',current_date-5,'end',current_date+5,'active',true,'indicator','c0de0000-0000-4000-8000-000000000002','events',1,'operations',1),'allowed narrowing persists dates/version and exactly one event/operation');
select lives_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),2,pg_temp.window_input(3,current_date-30,null,false),pg_temp.fixture('window-revoke'))$$,'revocation remains possible even when proposed date window grows');
select is(pg_temp.window_state(3,'window-revoke'),jsonb_build_object('version',3,'start',current_date-30,'end',null,'active',false,'indicator','c0de0000-0000-4000-8000-000000000002','events',2,'operations',1),'revocation persists inactive state and one additional event/operation');
select throws_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),3,pg_temp.window_input(3,current_date-30,null,true),pg_temp.fixture('window-reactivate'))$$,'22023','invalid_input','revoked association cannot reactivate in inactive scope');
select lives_ok($$select public.set_demo_business_link(pg_temp.admin_ctx(),pg_temp.fixture('window-actor'),1,pg_temp.window_input(3,current_date-5,current_date+5),pg_temp.fixture('window-narrow-current'))$$,'completed authorized replay precedes mutation-only inactive-scope policy');
select is(pg_temp.window_state(3,'window-reactivate'),jsonb_build_object('version',3,'start',current_date-30,'end',null,'active',false,'indicator','c0de0000-0000-4000-8000-000000000002','events',2,'operations',0),'rejected reactivation and completed replay do not mutate state/events');
select pg_temp.login_as('window-actor');
select ok(not exists(select 1 from jsonb_array_elements(public.get_authorized_contexts()->'contexts')c where c->>'vinculoId' in (pg_temp.fixture('window-link-1')::text,pg_temp.fixture('window-link-2')::text,pg_temp.fixture('window-link-3')::text,pg_temp.fixture('window-link-5')::text)),'unchanged expired/narrowed future/revoked/legacy have no context');
select ok(exists(select 1 from jsonb_array_elements(public.get_authorized_contexts()->'contexts')c where c->>'vinculoId'=pg_temp.fixture('window-link-4')::text),'narrowed valid fixed association retains context');
reset role;
update public.vinculos set ativo=false where actor_id=pg_temp.fixture('admin');
select pg_temp.login_as('admin');set local role authenticated;
select throws_ok($$select public.save_demo_scope(pg_temp.admin_ctx(),null,0,'{"codigo":"DEMO-NEW-DISTRICT","tipo":"distrito","distritoId":null,"ativo":true}',pg_temp.fixture('new-district-op'))$$,'42501','access_denied','revoked administrator cannot recover completed cache');
select throws_ok($$select public.get_admin_catalog(pg_temp.admin_ctx())$$,'42501','access_denied','catalogue rechecks current admin link');
select * from finish();rollback;
